 static struct rio_net *rio_scan_alloc_net(struct rio_mport *mport,
 					  int do_enum, u16 start)
 {
 	struct rio_net *net;

 	net = rio_alloc_net(mport);

 	if (net && do_enum) {
 		struct rio_id_table *idtab;
 		size_t size;

 		size = sizeof(struct rio_id_table) +
 				BITS_TO_LONGS(
 					RIO_MAX_ROUTE_ENTRIES(mport->sys_size)
 					) * sizeof(long);

 		idtab = kzalloc(size, GFP_KERNEL);

 		if (idtab == NULL) {
 			pr_err("RIO: failed to allocate destID table\n");
-			rio_free_net(net);
+			kfree(net);
+			mport->net = NULL;
 			net = NULL;
 		} else {
 			net->enum_data = idtab;
 			net->release = rio_scan_release_net;
 			idtab->start = start;
 			idtab->max = RIO_MAX_ROUTE_ENTRIES(mport->sys_size);
 			spin_lock_init(&idtab->lock);
 		}
 	}

 	if (net) {
 		net->id = mport->id;
 		net->hport = mport;
 		dev_set_name(&net->dev, "rnet_%d", net->id);
 		net->dev.parent = &mport->dev;
 		net->dev.release = rio_scan_release_dev;
 		if (rio_add_net(net)) {
 			put_device(&net->dev);
 			net = NULL;
 		}
 	}

 	return net;
 }



